INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '255acb66-61f3-5790-89a1-d1ec0e9836be', '878ac84c-54db-59b4-9ac5-b70ef33d5f15',
  '4. Giả sử biểu diễn đồ thị có trọng số G bằng ma trận kề M [7.1, 23]

