- (b) Nếu M không đối xứng qua đường chéo chính, thì G là có thể là đồ thị vô hướng
- (c) Số cạnh của đồ thị chính là số lượng giá trị khác 0 trong ma trận G
- (d) Cả A, B và C đều sai', 4
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
