);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '3e5f3b1b-79eb-5cc3-9e92-3b90441ab6a8', '878ac84c-54db-59b4-9ac5-b70ef33d5f15',
  '6. Cho hàm đệ quy sau:
