- (b) Hàm đệ quy trên có điểm dừng
- (c) Hàm đệ quy trên sẽ xảy ra lỗi khi gọi hàm với tham số thực có giá trị âm
- (d) Cả a, b, c đều sai', 6
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
