INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '8ccddc96-0f0f-57da-9b25-c2699b4e7f31', '878ac84c-54db-59b4-9ac5-b70ef33d5f15',
  '9. Sử dụng giải thuật Prim để tìm cây phủ tối thiểu đối với đồ thị sau. Biết rằng bắt đầu từ đỉnh 0, hãy cho biết thứ tự các cạnh được chọn để thêm vào cây phủ tối thiểu. [7.7, 22]

