INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'df29d96f-091f-5bdd-8141-a709d7fcb5b6', '878ac84c-54db-59b4-9ac5-b70ef33d5f15',
  '13. Giả sử dùng mảng $A[0..m - 1]$ để hiện thực hàng đợi vòng (circular queue), biết rằng vị trí của đầu và cuối là front và rear, thì [2.1, 14]

